"""Reproducible search for the GRI static formulation (dev-04).
Stages: (1) constant-rate scan to learn achievable TIR / pacing,
(2) random search over responsive shapes, (3) local refinement,
(4) safety-margin filtering and atomic checkpointing of design.json.
Usage: python search.py {scan,random,refine}
"""
import json, sys, time
import numpy as np
from gri_bench.api import load_instance, Experiment, save_design, PARAMETERS

inst = load_instance()
B = inst['bounds']
exp = Experiment(inst)


def score(m):
    """Rank feasible designs; require extra safety margin for held-out seeds."""
    if not m['feasible']:
        return -1e6 + m['mean_tir']
    pen = 0.0
    pen += 400.0 * max(0.0, m['max_trajectory_tbr70'] - 1.0)
    pen += 800.0 * max(0.0, m['max_trajectory_tbr54'] - 0.2)
    pen += 4.0 * max(0.0, 65.0 - m['minimum_glucose'])
    return m['mean_tir'] - pen


def clip(d):
    return {k: float(np.clip(v, *B[k])) for k, v in d.items()}


def run(d):
    d = clip(d)
    m = exp.evaluate({'mode': 'responsive', 'parameters': d})
    return score(m), m, d


def report(tag, s, m, d):
    print(f"{tag} score={s:7.2f} tir={m['mean_tir']:6.2f} tbr70={m['max_trajectory_tbr70']:.2f} "
          f"tbr54={m['max_trajectory_tbr54']:.2f} min={m['minimum_glucose']:6.1f} "
          + json.dumps({k: round(v, 6) for k, v in d.items()}))


if __name__ == '__main__':
    stage = sys.argv[1] if len(sys.argv) > 1 else 'random'
    if stage == 'scan':
        for tc in [1.25/4320, 1.6/4320, 2.0/4320, 2.5/4320, 3.0/4320]:
            for L in [1.25]:
                d = {'theta_c': tc, 'theta_L': L}
                m = exp.evaluate({'mode': 'constant', 'parameters': d})
                report(f'const tc={tc:.6f} L={L}', score(m), m, d)
    elif stage == 'random':
        rng = np.random.default_rng(7)
        best = (-1e9, None, None)
        for i in range(70):
            d = {'theta_a': float(10**rng.uniform(-4.2, -2.2)),
                 'relative_leak': float(rng.uniform(*B['relative_leak'])),
                 'ec50_mg_dl': float(10**rng.uniform(np.log10(70), np.log10(500))),
                 'hill_n': float(10**rng.uniform(np.log10(0.8), np.log10(12))),
                 'tau_min': float(10**rng.uniform(np.log10(0.2), np.log10(20))),
                 'theta_L': float(rng.uniform(0.75, 1.25))}
            s, m, d = run(d)
            if s > best[0]:
                best = (s, m, d); report(f'rnd{i}*', s, m, d)
        print('BEST', json.dumps(best[2]), best[0])
    else:
        base = json.loads(open('design.json').read())['parameters']
        rng = np.random.default_rng(11)
        best = run(base); report('seed', *best)
        step = {'theta_a': .35, 'relative_leak': .35, 'ec50_mg_dl': .25, 'hill_n': .35,
                'tau_min': .5, 'theta_L': .2}
        for it in range(60):
            d = best[2]
            cand = {}
            for k, v in d.items():
                if k in ('ec50_mg_dl', 'hill_n', 'tau_min', 'theta_a'):
                    cand[k] = float(v * np.exp(rng.normal(0, step[k])))
                else:
                    cand[k] = float(v * (1 + rng.normal(0, step[k])))
            s, m, dd = run(cand)
            if s > best[0]:
                best = (s, m, dd); report(f'ref{it}*', s, m, dd)
        print('BEST', json.dumps(best[2]), best[0])
        save_design({'mode': 'responsive', 'parameters': best[2]})
        summary = {k: v for k, v in best[1].items() if k != 'rows'}
        json.dump(summary, open('last_metrics.json', 'w'), indent=2)
        for r in best[1]['rows']:
            print(r['patient'], r['variant'], {k: round(v, 1) for k, v in r['metrics'].items()})
