{"command": "cd /work/output && python -c "
import json, numpy as np
from gri_bench.api import load_instance, Experiment, save_design
inst=load_instance()
base=json.load(open('design.json'))['parameters']
B=inst['bounds']
e2=Experiment(inst,seeds=[6111004,7777001])
def clip(d): return {k: float(np.clip(v,*B[k])) for k,v in d.items()}
def sc(m):
    if not m['feasible']: return -1e6
    return m['mean_tir'] - 4*max(0,65-m['minimum_glucose']) - 300*max(0,m['max_trajectory_tbr70']-1)
best=(sc(e2.evaluate({'mode':'responsive','parameters':base})),base)
rng=np.random.default_rng(21)
sdev={'theta_a':0.22,'relative_leak':0.25,'ec50_mg_dl':0.18,'hill_n':0.3,'tau_min':0.6,'theta_L':0.06}
for i in range(14):
    c=clip({k:float(v*np.exp(rng.normal(0,sdev[k]))) for k,v in best[1].items()})
    s=sc(e2.evaluate({'mode':'responsive','parameters':c}))
    if s>best[0]: best=(s,c); print(i,round(s,2),json.dumps({k:round(v,5) for k,v in c.items()}))
print('FINAL',best[0],json.dumps(best[1]))
save_design({'mode':'responsive','parameters':best[1]})
m=Experiment(inst).evaluate({'mode':'responsive','parameters':best[1]})
print({k:(round(v,2) if isinstance(v,float) else v) for k,v in m.items() if k!='rows'})
""}
